function minimumSeconds(nums) {
  const n = nums.length;
  const positions = new Map();
  for (let i = 0; i < n; i++) {
    if (!positions.has(nums[i])) {
      positions.set(nums[i], []);
    }
    positions.get(nums[i]).push(i);
  }
  let best = n;
  for (const indices of positions.values()) {
    let widest = indices[0] + n - indices[indices.length - 1];
    for (let k = 1; k < indices.length; k++) {
      widest = Math.max(widest, indices[k] - indices[k - 1]);
    }
    best = Math.min(best, Math.floor(widest / 2));
  }
  return best;
}

