function minimumSeconds(nums) {
  // Simulate: for each final value x, let x spread one step left and right per second.
  const n = nums.length;
  let best = Infinity;
  for (const x of new Set(nums)) {
    let current = nums.map(v => v === x);
    let seconds = 0;
    while (current.some(v => !v)) {
      current = current.map((v, i) => v || current[(i - 1 + n) % n] || current[(i + 1) % n]);
      seconds++;
    }
    best = Math.min(best, seconds);
  }
  return best;
}

