function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const distinct = [1, 2, 5, 40, 2000][Math.floor(rand() * 5)];
    const values = Array.from({ length: distinct }, () => 1 + Math.floor(rand() * 1000000000));
    return [Array.from({ length: n }, () => values[Math.floor(rand() * distinct)])];
  }
  const n = 1 + Math.floor(rand() * 10);
  const distinct = 1 + Math.floor(rand() * Math.min(n, 4));
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * distinct))];
}
